module.exports=({img})=>{
 const asset=f=>'../investor-20261010/'+f;
 const map=`<div class="td-platform-system" aria-label="AI 저작도구에서 제작한 콘텐츠를 학습 앱과 교구로 제공하고, 같은 콘텐츠를 홍보에 활용하는 구조">
 <div class="td-system-main">
 <article><span class="v-label">01 · 제작</span><h3>AI 저작도구</h3><div class="td-system-picture">${img(asset('authoring-overview-concept.png'),'콘텐츠 저작도구 구성 예시')}</div><p>이야기 · 삽화 · 음성 · 번역</p><b>AI 제작 + 편집자 검수</b></article>
 <span class="td-system-arrow" aria-hidden="true">→</span>
 <article><span class="v-label">02 · 콘텐츠</span><h3>학습 콘텐츠</h3><div class="td-system-library"><figure>${img(asset('phonics-covers/ko-1-chapter-v3.webp'),'한글 파닉스 문자 예시')}<figcaption>한글·영어 파닉스</figcaption></figure><figure>${img('cover-1789350946382.webp','거인의 정원 동화책 표지')}<figcaption>동화책 · 독후활동</figcaption></figure></div><b>글자 학습부터 이야기 이해까지</b></article>
 <span class="td-system-arrow td-system-branch" aria-hidden="true"><i>›</i><i>›</i></span>
 <article class="td-system-learning"><span class="v-label">03 · 학습 제공</span><h3>학습 앱 + 실물 교구</h3><div class="td-system-picture">${img(asset('app-overview-v3.webp'),'탱고북 학습 앱 디자인 예시')}</div><b>탱고 블록·탱고노트 연동</b></article>
 <article class="td-system-promotion"><span class="v-label">04 · 판매 지원</span><h3>AI 마케팅 도구</h3><div class="td-system-channels">${['naver','google','youtube','instagram'].map(name=>img(asset('channel-logos/'+name+'.svg'),name)).join('')}</div><p>콘텐츠로 홍보물 생성 · 검수 · 자동 발행</p><b>검색·SNS 마케팅 → 유통사 판매 지원</b></article>
 </div>
 </div><p class="td-note">제작한 콘텐츠를 학습 서비스와 홍보에 함께 활용하는 구조입니다. 화면은 구성 예시입니다.</p>`;
 const css=`
 .td-system-main{display:grid;grid-template-columns:1fr 32px 1fr 32px 1fr;gap:12px;align-items:stretch}.td-system-main article{padding:22px;border:1px solid var(--doc-color-line);border-top:3px solid var(--doc-color-teal);border-radius:8px;min-width:0}.td-system-main h3{font-size:24px;line-height:1.3;margin:10px 0 20px}.td-system-main p{font-size:16px;margin:18px 0 8px}.td-system-main article>b{display:block;font-size:15px;color:var(--doc-color-teal)}.td-system-arrow{align-self:center;text-align:center;font-size:30px;color:var(--doc-color-teal)}.td-system-picture{height:185px;display:flex;align-items:center}.td-system-picture img{width:100%;height:100%!important;object-fit:contain;border-radius:6px}.td-system-library{display:grid;grid-template-columns:1fr 1fr;gap:12px;height:185px;align-items:center}.td-system-library figure{min-width:0}.td-system-library img{width:100%;height:140px!important;object-fit:cover;border-radius:6px}.td-system-library figcaption{word-break:keep-all;font-size:14px;margin-top:8px;color:var(--doc-color-ink)}.td-system-link{display:flex;align-items:center;justify-content:center;gap:14px;font-size:17px;color:var(--doc-color-teal);padding:14px}.td-system-link>span{font-size:28px}.td-system-marketing{display:grid;grid-template-columns:220px 1fr;gap:24px;align-items:center;padding:24px;background:var(--doc-color-wash);border-left:4px solid var(--doc-color-teal)}.td-system-marketing h3{font-size:25px;margin:7px 0 0}.td-system-stages{display:flex;align-items:center;justify-content:space-between;gap:14px;font-size:20px}.td-system-stages>span{color:var(--doc-color-teal)}

 .td-platform-system{padding:24px;background:var(--doc-color-wash);border:1px solid var(--doc-color-line);border-radius:12px}
 .td-system-main{grid-template-columns:1fr 32px 1fr 48px 1.15fr;grid-template-rows:1fr 1fr;gap:18px 8px}
 .td-system-main>article{background:white;display:flex;flex-direction:column;justify-content:center;padding:22px}
 .td-system-main>article:nth-child(1){grid-column:1;grid-row:1/3;align-self:center}
 .td-system-main>article:nth-child(1) .td-system-picture{height:auto;aspect-ratio:16/9}
 .td-system-main>article:nth-child(3){grid-column:3;grid-row:1/3;align-self:center}
 .td-system-main>.td-system-arrow:nth-child(2){grid-column:2;grid-row:1/3}
 .td-system-main>.td-system-arrow:nth-child(4){grid-column:4;grid-row:1/3;font-size:0;align-self:stretch;position:relative}
 .td-system-main>.td-system-arrow:nth-child(4):before{content:'';position:absolute;left:10px;right:0;top:25%;bottom:25%;border:2px solid var(--doc-color-teal);border-right:0}
 .td-system-branch i{position:absolute;right:-2px;top:25%;font-size:30px;font-style:normal;line-height:1;transform:translateY(-50%)}.td-system-branch i:last-child{top:75%}
 .td-system-main>.td-system-arrow:nth-child(4):after{content:'';position:absolute;left:0;top:50%;width:10px;border-top:2px solid var(--doc-color-teal)}
 .td-system-main>.td-system-learning{grid-column:5;grid-row:1;min-height:270px}
 .td-system-main>.td-system-promotion{grid-column:5;grid-row:2;min-height:270px}
 .td-system-learning .td-system-picture{height:110px}
 .td-system-main h3{font-size:23px;margin:8px 0 14px}
 .td-system-main p{font-size:15px;margin:12px 0 6px}
 .td-system-main article>b{font-size:14px}
 .td-system-channels{display:flex;align-items:center;gap:18px;height:56px}
 .td-system-channels img{width:34px;height:34px!important;object-fit:contain}
 .td-offer-hardware small,.td-offer-app small{display:block;font-size:12px;line-height:1.5;margin-top:6px}.td-offer-access.td-offer-app{background:var(--doc-color-wash);color:var(--doc-color-ink);justify-content:flex-start}.td-offer-app img{height:130px!important;width:100%;object-fit:contain}.td-offer-app b{font-size:18px;line-height:1.5;margin-top:10px}
 .td-offer-grid>article:first-child .td-offer-contents img{height:185px!important;width:100%;object-fit:contain}.td-offer-grid>article:first-child .td-offer-contents{margin-bottom:12px;gap:12px}.td-offer-grid>article:first-child .td-offer-hardware,.td-offer-grid>article:first-child .td-offer-app{padding:8px}.td-offer-grid>article:first-child .td-offer-list li{padding:5px 0}.td-offer-grid>article:first-child .td-offer-list{margin-bottom:12px}
 @media(max-width:699px){.td-platform-system{padding:16px}.td-system-main{grid-template-columns:1fr;grid-template-rows:auto}.td-system-main>article:nth-child(n),.td-system-main>.td-system-arrow:nth-child(n){grid-column:auto;grid-row:auto}.td-system-main>.td-system-arrow:nth-child(4){display:none}.td-system-main>.td-system-learning{margin-top:12px}}
 #investor-panel .td-activity-pair figure img{height:365px!important;max-height:none;aspect-ratio:auto;object-fit:contain}.td-activity-pair article{padding:18px}.td-activity-pair .td-activity-heading h3{font-size:25px}.td-activity-pair article>p{font-size:17px}
 .td-product-status{display:inline-block;font-size:13px;color:var(--doc-color-teal);background:var(--doc-color-wash);padding:5px 10px;margin-bottom:12px;border-radius:5px}.td-product-status.planned{color:#9d5038;background:#f9ede6}.td-status-line{font-size:14px;color:var(--doc-color-muted);border-top:1px solid var(--doc-color-line);padding-top:12px;margin-top:18px}
 .td-offer-grid{display:grid;grid-template-columns:1.3fr 1fr;gap:28px}.td-offer-grid>article{display:flex;flex-direction:column;padding:22px;border:1px solid var(--doc-color-line);border-top:4px solid var(--doc-color-teal);border-radius:8px}.td-offer-grid>article:last-child{border-top-color:var(--doc-color-coral)}.td-offer-grid h3{font-size:26px;line-height:1.35;min-height:71px;margin:10px 0 16px}.td-offer-contents{display:grid;grid-template-columns:1fr 1fr;gap:16px;align-items:stretch;margin-bottom:20px}.td-offer-hardware,.td-offer-access{padding:14px;background:var(--doc-color-wash);border-radius:8px;text-align:center}.td-offer-hardware img{height:130px!important;width:100%;object-fit:contain;mix-blend-mode:multiply}.td-offer-hardware b{display:block;font-size:19px;margin-top:10px}.td-offer-access{display:flex;flex-direction:column;justify-content:center;background:var(--doc-color-ink);color:var(--doc-color-paper)}.td-offer-access strong{font-size:54px;line-height:1.3}.td-offer-access strong small{font-size:20px}.td-offer-access span{font-size:15px}.td-offer-list{list-style:none;margin:0;padding:0;font-size:17px;line-height:1.65}.td-offer-list li{padding:8px 0;border-bottom:1px solid var(--doc-color-line)}.td-offer-list{margin-bottom:20px}.td-offer-price{display:flex;align-items:baseline;justify-content:space-between;border-top:2px solid var(--doc-color-teal);margin-top:auto;padding-top:16px}.td-offer-price>span{font-size:14px}.td-offer-price strong{font-size:34px}.td-offer-price small{font-size:17px}.td-note-offer{display:flex;gap:20px;align-items:center;height:197px;margin-bottom:20px}.td-note-offer img{width:55%;height:170px!important;object-fit:contain}.td-note-offer b{font-size:21px;line-height:1.6}.td-note-offer b small{display:block;font-weight:400;font-size:14px;margin-top:10px}
 @media(max-width:699px){.td-system-main{grid-template-columns:1fr}.td-system-arrow{transform:rotate(90deg)}.td-system-picture{height:180px}.td-system-marketing{grid-template-columns:1fr}.td-system-stages{font-size:15px;gap:6px;flex-wrap:wrap}.td-system-link{font-size:14px}.td-offer-grid{grid-template-columns:1fr}.td-offer-grid>article{padding:20px}#investor-panel .td-activity-pair figure img{height:auto!important;max-height:none}.td-system-main h3{font-size:25px}}
 `;
 return {map,css:css.trim()};
};
